-- Preserve inheritance and every customized template. Scope title is occasionTitle at this published boundary.
UPDATE public.email_templates SET subject='Pozvánka ke spolupráci - {{occasionTitle}}',html='<h2>Pozvánka ke spolupráci: {{occasionTitle}}</h2><p>{{appName}} nabízí oprávnění {{roleLabel}}.</p><p><a href="{{invitationUrl}}">Zobrazit a přijmout pozvánku</a></p><p>Pozvánka platí 14 dní. Přihlaste se pozvaným účtem nebo si vytvořte nový účet s vlastním heslem.</p>' WHERE code='TEAM_INVITATION' AND organization IS NULL AND unit IS NULL AND occasion IS NULL AND subject='Pozvánka ke správě akce - {{occasionTitle}}' AND html='<h2>Pozvánka do týmu akce {{occasionTitle}}</h2><p>{{appName}} zve ke spolupráci na správě akce s oprávněním {{roleLabel}}.</p><p><a href="{{invitationUrl}}">Zobrazit a přijmout pozvánku</a></p><p>Pozvánka platí 14 dní. Přijetí vyžaduje přihlášení k pozvanému účtu nebo vytvoření nového účtu s vlastním heslem.</p>';
UPDATE public.email_templates SET subject='Přístup - {{occasionTitle}}',html='<h2>Přístup: {{occasionTitle}}</h2><p>V aplikaci {{appName}} máte přístup s oprávněním {{roleLabel}}.</p><p><a href="{{occasionAdminUrl}}">Otevřít správu</a></p><p>Přihlaste se svým účtem. Pokud heslo neznáte, použijte obnovu hesla. Tato zpráva heslo nemění.</p>' WHERE code='TEAM_ACCESS_NOTICE' AND organization IS NULL AND unit IS NULL AND occasion IS NULL AND subject='Přístup k akci - {{occasionTitle}}' AND html='<h2>Přístup k akci {{occasionTitle}}</h2><p>V aplikaci {{appName}} je dostupná akce s oprávněním {{roleLabel}}.</p><p><a href="{{occasionAdminUrl}}">Otevřít správu akce</a></p><p>Přihlaste se svým účtem. Pokud heslo neznáte, použijte na přihlašovací stránce odkaz pro obnovu hesla. Tato zpráva heslo nemění.</p>';
